arguments.file_text:
@using sv_bb848b46b8d0485ca72d1687b5ec43c5.Services

<div class="kanban-card">
    <h4 class="kanban-card-title">@Task.Title</h4>
    <p class="kanban-card-assignee">@Task.Assignee</p>
    <span class="priority-badge priority-@Task.Priority.ToLowerInvariant()">@Task.Priority</span>
    <span class="kanban-card-due">@Task.DueDate.ToString("MMM dd")</span>
    <div class="kanban-card-actions">
        @if (CanMoveLeft)
        {
            <button class="btn btn-sm btn-move" @onclick="OnMoveLeft">Move Left</button>
        }
        @if (CanMoveRight)
        {
            <button class="btn btn-sm btn-move" @onclick="OnMoveRight">Move Right</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public TaskItem Task { get; set; } = default!;
    [Parameter] public bool CanMoveLeft { get; set; }
    [Parameter] public bool CanMoveRight { get; set; }
    [Parameter] public EventCallback MoveLeft { get; set; }
    [Parameter] public EventCallback MoveRight { get; set; }

    private async System.Threading.Tasks.Task OnMoveLeft() => await MoveLeft.InvokeAsync();
    private async System.Threading.Tasks.Task OnMoveRight() => await MoveRight.InvokeAsync();
}

@using sv_bb848b46b8d0485ca72d1687b5ec43c5.Services

<div class="kanban-column">
    <div class="kanban-column-header">
        <h3>@Title (@Tasks.Count)</h3>
    </div>
    <div class="kanban-column-body">
        @foreach (var task in Tasks)
        {
            <KanbanTaskCard Task="task"
                           CanMoveLeft="CanMoveLeft"
                           CanMoveRight="CanMoveRight"
                           MoveLeft="() => OnMoveTask.InvokeAsync((task.Id, MoveLeftStatus!))"
                           MoveRight="() => OnMoveTask.InvokeAsync((task.Id, MoveRightStatus!))" />
        }
    </div>
    <div class="kanban-column-footer">
        @if (showAddForm)
        {
            <KanbanAddTaskForm OnSave="HandleAddTask" OnCancel="() => showAddForm = false" />
        }
        else
        {
            <button class="btn btn-outline btn-add-task" @onclick="() => showAddForm = true">Add Task</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string Title { get; set; } = string.Empty;
    [Parameter, EditorRequired] public List<TaskItem> Tasks { get; set; } = new();
    [Parameter] public bool CanMoveLeft { get; set; }
    [Parameter] public bool CanMoveRight { get; set; }
    [Parameter] public string? MoveLeftStatus { get; set; }
    [Parameter] public string? MoveRightStatus { get; set; }
    [Parameter] public EventCallback<(int TaskId, string NewStatus)> OnMoveTask { get; set; }
    [Parameter] public EventCallback<(string Title, string Assignee, string Priority, DateTime DueDate)> OnAddTask { get; set; }

    private bool showAddForm;

    private async Task HandleAddTask((string Title, string Assignee, string Priority, DateTime DueDate) formData)
    {
        await OnAddTask.InvokeAsync(formData);
        showAddForm = false;
    }
}

@using sv_bb848b46b8d0485ca72d1687b5ec43c5.Services

<div class="kanban-stats">
    <div class="stat-item">
        <span class="stat-label">Total</span>
        <span class="stat-value">@Total</span>
    </div>
    <div class="stat-item">
        <span class="stat-label">To Do</span>
        <span class="stat-value">@ToDo</span>
    </div>
    <div class="stat-item">
        <span class="stat-label">In Progress</span>
        <span class="stat-value">@InProgress</span>
    </div>
    <div class="stat-item">
        <span class="stat-label">Done</span>
        <span class="stat-value">@Done</span>
    </div>
    <div class="stat-item stat-overdue">
        <span class="stat-label">Overdue</span>
        <span class="stat-value">@Overdue</span>
    </div>
</div>

@code {
    [Parameter] public List<TaskItem> Tasks { get; set; } = new();

    private int Total => Tasks.Count;
    private int ToDo => Tasks.Count(t => t.Status == "To Do");
    private int InProgress => Tasks.Count(t => t.Status == "In Progress");
    private int Done => Tasks.Count(t => t.Status == "Done");
    private int Overdue => Tasks.Count(t => t.DueDate < DateTime.Today && t.Status != "Done");
}

@page "/board"
@using sv_bb848b46b8d0485ca72d1687b5ec43c5.Services
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h1>Kanban Board</h1>

@if (loading)
{
    <p class="loading-message">Loading tasks...</p>
}
else if (errorMessage is not null)
{
    <div class="error-message">
        <p>@errorMessage</p>
        <button class="btn btn-primary" @onclick="LoadTasks">Retry</button>
    </div>
}
else
{
    <KanbanStats Tasks="tasks" />
    <KanbanSearchBar SearchText="@searchText" SearchTextChanged="HandleSearchChanged" />

    <div class="kanban-board">
        <KanbanColumn Title="To Do"
                      Tasks="FilteredTasks("To Do")"
                      CanMoveLeft="false"
                      CanMoveRight="true"
                      MoveRightStatus="In Progress"
                      OnMoveTask="HandleMoveTask"
                      OnAddTask="args => HandleAddTask(args, "To Do")" />

        <KanbanColumn Title="In Progress"
                      Tasks="FilteredTasks("In Progress")"
                      CanMoveLeft="true"
                      CanMoveRight="true"
                      MoveLeftStatus="To Do"
                      MoveRightStatus="Done"
                      OnMoveTask="HandleMoveTask"
                      OnAddTask="args => HandleAddTask(args, "In Progress")" />

        <KanbanColumn Title="Done"
                      Tasks="FilteredTasks("Done")"
                      CanMoveLeft="true"
                      CanMoveRight="false"
                      MoveLeftStatus="In Progress"
                      OnMoveTask="HandleMoveTask"
                      OnAddTask="args => HandleAddTask(args, "Done")" />
    </div>
}

@code {
    private List<TaskItem> tasks = new();
    private string searchText = string.Empty;
    private bool loading = true;
    private string? errorMessage;

    protected override async Task OnInitializedAsync()
    {
        await LoadTasks();
    }

    private async Task LoadTasks()
    {
        try
        {
            loading = true;
            errorMessage = null;
            tasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            loading = false;
        }
    }

    private List<TaskItem> FilteredTasks(string status)
    {
        var filtered = tasks.Where(t => t.Status == status);
        if (!string.IsNullOrWhiteSpace(searchText))
        {
            filtered = filtered.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase));
        }
        return filtered.ToList();
    }

    private void HandleSearchChanged(string value)
    {
        searchText = value;
    }

    private async Task HandleMoveTask((int TaskId, string NewStatus) move)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(move.TaskId, move.NewStatus);
            var task = tasks.First(t => t.Id == move.TaskId);
            var index = tasks.IndexOf(task);
            tasks[index] = task with { Status = move.NewStatus };
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private async Task HandleAddTask((string Title, string Assignee, string Priority, DateTime DueDate) formData, string status)
    {
        try
        {
            var newTask = await TaskService.CreateTaskAsync(formData.Title, formData.Assignee, formData.Priority, formData.DueDate);
            tasks.Add(newTask with { Status = status });
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to create task: {ex.Message}";
        }
    }
}

