     private const string StatusToDo = "To Do";
     private const string StatusInProgress = "In Progress";
     private const string StatusDone = "Done";

     private List<TaskItem> tasks = new();
     private string searchText = string.Empty;
     private bool loading = true;
     private string? errorMessage;

     protected override async Task OnInitializedAsync()
     {
         await LoadTasks();
     }

     private async Task LoadTasks()
     {
         try
         {
             loading = true;
             errorMessage = null;
             tasks = await TaskService.GetAllTasksAsync();
         }
         catch (Exception ex)
         {
             errorMessage = $"Failed to load tasks: {ex.Message}";
         }
         finally
         {
             loading = false;
         }
     }

     private List<TaskItem> FilteredTasks(string status)
     {
         var filtered = tasks.Where(t => t.Status == status);
         if (!string.IsNullOrWhiteSpace(searchText))
         {
             filtered = filtered.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase));
         }
         return filtered.ToList();
     }

     private void HandleSearchChanged(string value)
     {
         searchText = value;
     }

     private async Task HandleMoveTask((int TaskId, string NewStatus) move)
     {
         try
         {
             await TaskService.UpdateTaskStatusAsync(move.TaskId, move.NewStatus);
             var task = tasks.First(t => t.Id == move.TaskId);
             var index = tasks.IndexOf(task);
             tasks[index] = task with { Status = move.NewStatus };
         }
         catch (Exception ex)
         {
             errorMessage = $"Failed to move task: {ex.Message}";
         }
     }

     private async Task HandleAddTask((string Title, string Assignee, string Priority, DateTime DueDate) formData, string status)
     {
         try
         {
             var newTask = await TaskService.CreateTaskAsync(formData.Title, formData.Assignee, formData.Priority, formData.DueDate);
             tasks.Add(newTask with { Status = status });
         }
         catch (Exception ex)
         {
             errorMessage = $"Failed to create task: {ex.Message}";
         }
     }
 }

